package io.github.codexpocket.app;
import android.content.*;
import android.graphics.BitmapFactory;
import org.json.*;
import java.io.*;
import java.nio.*;
import java.nio.charset.*;
import java.nio.file.*;
/** Private one-shot queue. Exported Activity intents can identify an entry, never supply its content. */
final class AdbImports {
 record Payload(String command,String mime,byte[] bytes){}
 private static final String SESSION=java.util.UUID.randomUUID().toString();
 private static final int HISTORY_LIMIT=512,QUEUE_LIMIT=4;private static final long EXPIRY=120000;
 private static SharedPreferences meta(Context c){return history(c);}
 private static long epoch(Context c){return meta(c).getLong("epoch",0);}
 private static boolean currentId(Context c,String id){return AdbImportPolicy.currentId(id,epoch(c));}
 private static SharedPreferences history(Context c){return c.getSharedPreferences("adb_import_history",Context.MODE_PRIVATE);}
 private static Path stage(Context c)throws IOException{Path dir=c.getFilesDir().toPath().resolve("adb-imports");Files.createDirectories(dir);return dir;}
 private static java.util.List<String> ids(Context c){java.util.List<String> out=new java.util.ArrayList<>();for(String key:history(c).getAll().keySet())if(key.startsWith("request:"))out.add(key.substring(8));return out;}
 private static JSONObject record(Context c,String id)throws JSONException{String value=history(c).getString("request:"+id,null);return value==null?null:new JSONObject(value);}
 private static void save(Context c,String id,JSONObject value)throws Exception{if(!history(c).edit().putString("request:"+id,value.toString()).commit())throw new IOException("storage_error");}
 private static JSONObject result(Context c,String id,String command,String status,String code)throws Exception{return new JSONObject().put("version",1).put("request_id",id).put("command",java.util.Set.of("init","status","reset-history","import-pairing","import-image").contains(command==null?"":command)?command:"unknown").put("status",status).put("code",code).put("updated_at",System.currentTimeMillis()).put("history_epoch",epoch(c)).put("history_size",ids(c).size()).put("paired",new Credentials(c).read()!=null);}
 private static void publish(Context c,AdbFiles files,JSONObject result)throws Exception{files.result(result.getString("request_id"),result.toString());JSONObject status=new JSONObject().put("version",1).put("app_version",BuildConfig.VERSION_NAME).put("status","ok").put("paired",new Credentials(c).read()!=null).put("history_epoch",epoch(c)).put("history_size",ids(c).size()).put("directories_ready",true).put("queued",queued(c)).put("last_request_id",result.getString("request_id")).put("updated_at",System.currentTimeMillis());files.status(status.toString());}
 private static int queued(Context c)throws Exception{int count=0;for(String id:ids(c)){JSONObject r=record(c,id);if(r!=null&&("queued".equals(r.optString("status"))||"processing".equals(r.optString("status"))))count++;}return count;}
 private static int staged(Context c)throws IOException{int count=0;try(DirectoryStream<Path> paths=Files.newDirectoryStream(stage(c),"*.bin")){for(Path path:paths)count++;}return count;}
 private static void launch(Context c,String id){Intent intent=new Intent(c,MainActivity.class).setAction(AdbCommandReceiver.IMPORT_ACTION).putExtra("request_id",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP);c.startActivity(intent);}
 static synchronized void command(Context c,String id,String command,String file)throws Exception{
  AdbFiles files=new AdbFiles(c.getExternalFilesDir(null));cleanup(c);JSONObject output;
  if("init".equals(command)||"status".equals(command)){publish(c,files,result(c,id,command,"ok","ready"));return;}
  if("reset-history".equals(command)){if(id.equals(meta(c).getString("last_reset_id",""))){publish(c,files,result(c,id,command,"ok","history_reset"));return;}if(!currentId(c,id)){publish(c,files,result(c,id,command,"error","request_epoch"));return;}if(queued(c)>0){publish(c,files,result(c,id,command,"error","busy"));return;}if(!history(c).edit().clear().putLong("epoch",epoch(c)+1).putString("last_reset_id",id).commit())throw new IOException("storage_error");try(DirectoryStream<Path> paths=Files.newDirectoryStream(stage(c),"*.bin")){for(Path path:paths)Files.deleteIfExists(path);}publish(c,files,result(c,id,command,"ok","history_reset"));return;}
  if(!"import-pairing".equals(command)&&!"import-image".equals(command)){publish(c,files,result(c,id,command,"error","invalid_command"));return;}
  if(!currentId(c,id)){publish(c,files,result(c,id,command,"error","request_epoch").put("input_consumed",false));return;}
  if(!AdbFiles.basename(file)){publish(c,files,result(c,id,command,"error","invalid_file").put("input_consumed",false));return;}
  JSONObject known=record(c,id);if(known!=null&&!files.exists(file)){if(!command.equals(known.optString("command"))||!java.util.Objects.equals(file,known.optString("source_file"))){publish(c,files,result(c,id,command,"error","request_conflict"));return;}String state=known.optString("status");publish(c,files,result(c,id,command,state,known.optString("code")).put("input_consumed",true));if(state.equals("queued"))try{launch(c,id);}catch(Exception ignored){}return;}
  byte[] bytes=null;boolean consumed=false;String hash=null;
  try{
   bytes=files.read(file,"import-pairing".equals(command)?AdbFiles.PAIR_LIMIT:AdbFiles.IMAGE_LIMIT);
   hash=AdbFiles.hash(command,bytes);JSONObject previous=record(c,id);
   if(previous!=null){if(!AdbImportPolicy.sameContent(previous.optString("hash"),hash)){publish(c,files,result(c,id,command,"error","request_conflict").put("input_consumed",false));return;}String state=previous.optString("status");if(java.util.Set.of("queued","processing","prepared").contains(state)){files.consume(file);consumed=true;}output=result(c,id,command,state,previous.optString("code")).put("input_consumed",consumed);publish(c,files,output);if("queued".equals(state))try{launch(c,id);}catch(Exception ignored){}return;}
   if(ids(c).size()>=HISTORY_LIMIT)throw new IOException("history_full");if(staged(c)>=QUEUE_LIMIT)throw new IOException("queue_full");String mime="";
   if("import-pairing".equals(command)){String raw=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();JSONObject pair=new JSONObject(raw);if(!"codex-pocket-pair".equals(pair.optString("type"))||pair.optInt("version")!=1||pair.optString("ticket").length()<16||pair.optString("ticket").length()>256)throw new IOException("invalid_pairing");}
   else{mime=AdbFiles.mime(file,bytes);BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<=0||options.outHeight<=0||options.outWidth>16384||options.outHeight>16384||(long)options.outWidth*options.outHeight>40000000)throw new IOException("image_dimensions");}
   JSONObject entry=new JSONObject().put("source_file",file).put("command",command).put("mime",mime).put("hash",hash).put("status","queued").put("code","awaiting_ui").put("created_at",System.currentTimeMillis());files.stageAndConsume(file,stage(c),id,bytes,()->save(c,id,entry));consumed=true;publish(c,files,result(c,id,command,"queued","awaiting_ui").put("input_consumed",consumed));try{launch(c,id);}catch(Exception ignored){/* queued remains retryable via the same request/file */}
  }catch(Exception error){String code=error instanceof IOException?error.getMessage():"import-pairing".equals(command)?"invalid_pairing":"invalid_image";if(!java.util.Set.of("invalid_file","too_large","symlink_rejected","invalid_image","invalid_pairing","image_dimensions","history_full","queue_full").contains(code))code="storage_error";JSONObject saved=record(c,id);if(saved!=null&&"queued".equals(saved.optString("status"))&&AdbImportPolicy.sameContent(saved.optString("hash"),hash)){publish(c,files,result(c,id,command,"queued","awaiting_ui").put("input_consumed",consumed));return;}if(hash!=null&&ids(c).size()<HISTORY_LIMIT){JSONObject failed=new JSONObject().put("source_file",file).put("command",command).put("mime","").put("hash",hash).put("status","error").put("code",code).put("created_at",System.currentTimeMillis());save(c,id,failed);}publish(c,files,result(c,id,command,"error",code).put("input_consumed",consumed));}
 }
 static synchronized Payload take(Context c,String id)throws Exception{cleanup(c);if(!AdbFiles.requestId(id))return null;JSONObject entry=record(c,id);if(entry==null||!"queued".equals(entry.optString("status")))return null;Path path=stage(c).resolve(id+".bin");if(System.currentTimeMillis()-entry.optLong("created_at")>EXPIRY){Files.deleteIfExists(path);finish(c,id,false,"expired");return null;}int limit="import-pairing".equals(entry.optString("command"))?AdbFiles.PAIR_LIMIT:AdbFiles.IMAGE_LIMIT;if(!Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS)||Files.size(path)>limit)throw new IOException("invalid_stage");byte[] bytes;try(InputStream in=Files.newInputStream(path,LinkOption.NOFOLLOW_LINKS)){bytes=ApiClient.read(in,limit);}entry.put("status","processing").put("code","ui_processing").put("delivery_session",SESSION);save(c,id,entry);return new Payload(entry.getString("command"),entry.optString("mime"),bytes);}
 static synchronized boolean pending(Context c,String id){try{JSONObject entry=record(c,id);return entry!=null&&"queued".equals(entry.optString("status"));}catch(Exception e){return false;}}
 private static void cleanup(Context c)throws Exception{try(DirectoryStream<Path> paths=Files.newDirectoryStream(stage(c),"*.bin")){for(Path path:paths){String name=path.getFileName().toString();String id=name.substring(0,name.length()-4);if(!AdbFiles.requestId(id)||record(c,id)==null)Files.deleteIfExists(path);}}long now=System.currentTimeMillis();for(String id:ids(c)){JSONObject r=record(c,id);if(r==null)continue;if(now-r.optLong("created_at")>EXPIRY)Files.deleteIfExists(stage(c).resolve(id+".bin"));String state=r.optString("status");String recovery=AdbImportPolicy.recovery(state,now-r.optLong("created_at"),SESSION.equals(r.optString("delivery_session")));if(!recovery.isEmpty())finish(c,id,false,recovery);}}
 static synchronized void finish(Context c,String id,boolean success,String code){try{JSONObject entry=record(c,id);if(entry==null||!("processing".equals(entry.optString("status"))||"queued".equals(entry.optString("status"))))return;entry.put("status",success?"prepared":"error").put("code",code);save(c,id,entry);if(success)Files.deleteIfExists(stage(c).resolve(id+".bin"));publish(c,new AdbFiles(c.getExternalFilesDir(null)),result(c,id,entry.optString("command"),entry.getString("status"),code).put("input_consumed",true));}catch(Exception ignored){}}
}
